make_e_data <- function(){z<-read_input("association_values.csv");z<-z[match(c("Structure","BaselinePain","StructureBaselinePain","StructureClinic","BaselinePainClinic","Full"),z$model),];z$label<-c("Structure","Baseline pain","Baseline pain + structure","Structure + clinical","Baseline pain + clinical","Baseline pain + structure + clinical");z}
draw_e <- function(){z<-make_e_data();tx<-function(s,x,y,size=CFG$font_pt,bold=FALSE,just="left",col=CFG$ink){grid.text(s,x=x/183,y=y/40,just=just,gp=gpar(fontfamily=CFG$family,fontsize=size,col=col,fontface=if(bold)2 else 1))};ln<-function(x1,y1,x2,y2,lty=1,col=CFG$ink,lwd=.6){grid.lines(c(x1,x2)/183,c(y1,y2)/40,gp=gpar(col=col,lwd=lwd,lty=lty))};dot<-function(x,y,on,red=FALSE){grid.circle(x/183,y/40,r=unit(.48,"mm"),gp=gpar(fill=if(red)CFG$red else if(on)CFG$blue else "white",col=if(on||red)NA else "#BDC6D0",lwd=.5))};map<-function(v)107+(log(v)-log(.5))/(log(25)-log(.5))*37
 tx("e  Adjusted association with sustained follow-up pain",1,38,size=CFG$title_pt,bold=TRUE);ln(1,35.5,182,35.5,lwd=.8);tx("Adjustment set",1,33.3,bold=TRUE);for(j in 1:3)tx(c("Pain","X-ray","Clinical")[j],c(70,83,96)[j],33.3,bold=TRUE,just="center");tx("OR",125,33.3,bold=TRUE,just="center");tx("OR [95% CI]",150,33.3,bold=TRUE);ln(1,31.5,182,31.5);yy<-seq(27.9,9.9,length.out=6);ln(map(1),31.5,map(1),7.8,lty=2,col=CFG$grey);inc<-list(Structure=c(0,1,0),BaselinePain=c(1,0,0),StructureBaselinePain=c(1,1,0),StructureClinic=c(0,1,1),BaselinePainClinic=c(1,0,1),Full=c(1,1,1))
 for(i in 1:6){bold<-z$model[i]=="Full";tx(z$label[i],1,yy[i],bold=bold);for(j in 1:3)dot(c(70,83,96)[j],yy[i],inc[[z$model[i]]][j]==1);ln(map(z$lo[i]),yy[i],map(z$hi[i]),yy[i],col=CFG$blue,lwd=1);ln(map(z$lo[i]),yy[i]-.65,map(z$lo[i]),yy[i]+.65,col=CFG$blue);ln(map(z$hi[i]),yy[i]-.65,map(z$hi[i]),yy[i]+.65,col=CFG$blue);dot(map(z$OR[i]),yy[i],TRUE,TRUE);tx(sprintf("%.2f [%.2f, %.2f]",z$OR[i],z$lo[i],z$hi[i]),150,yy[i],bold=bold)}
 ln(1,7.8,182,7.8,lwd=.8);ln(map(.5),5.9,map(25),5.9);for(v in c(1,2,5,10,20)){ln(map(v),5.9,map(v),5.2);tx(as.character(v),map(v),4.1,size=CFG$min_font_pt,just="center")};tx("Odds ratio (log scale)",125,1.5,size=CFG$min_font_pt,just="center")}
